<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\LoadService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('LOAD_VIEW_OWN');$id=(int)($_GET['id']??0);$load=LoadService::find($id);if(!$load){http_response_code(404);exit('Load not found.');}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{LoadService::submit($id,(int)Auth::user()['id']);header('Location: '.Url::to('loads/view.php?id='.$id.'&submitted=1'));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}}$pageTitle='Load '.$load['load_ref'];require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1><?=h($load['load_ref'])?></h1><p><?=h($load['cargo_summary'])?></p></div><span class="badge"><?=h(ucwords(str_replace('_',' ',$load['current_status'])))?></span></div><?php if(isset($_GET['created'])):?><div class="success">Load draft created.</div><?php endif;if(isset($_GET['updated'])):?><div class="success">Load draft updated.</div><?php endif;if(isset($_GET['submitted'])):?><div class="success">Load submitted to McCollins Operations for review.</div><?php endif;if(isset($_GET['clarified'])):?><div class="success">Clarification response submitted as a new load version.</div><?php endif;foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?><div class="grid"><div class="card"><h3>Route</h3><p><strong>Pickup:</strong> <?=h($load['origin_line_1'].', '.$load['origin_city'])?></p><p><strong>Destination:</strong> <?=h($load['destination_line_1'].', '.$load['destination_city'])?></p></div><div class="card"><h3>Schedule</h3><p><strong>Pickup:</strong> <?=h($load['requested_pickup_from']?:'Not set')?> – <?=h($load['requested_pickup_to']?:'Not set')?></p><p><strong>Delivery:</strong> <?=h($load['requested_delivery_from']?:'Not set')?> – <?=h($load['requested_delivery_to']?:'Not set')?></p></div><div class="card"><h3>Cargo</h3><p><?=h($load['item_description'])?></p><p><?=h($load['quantity'].' '.$load['unit_code'])?></p></div></div><?php if($load['current_status']==='draft'):?><div class="card" style="margin-top:18px"><h3>Draft actions</h3><p>Submission locks this version for Operations review. It cannot be edited afterward.</p><div class="actions"><a class="button secondary" href="<?=h(Url::to('loads/edit.php?id='.$id))?>">Edit draft</a><form method="post"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><button class="button" type="submit">Submit for review</button></form></div></div><?php elseif($load['current_status']==='clarification_required'&&Auth::can('LOAD_CLARIFICATION_RESPOND_OWN')):?><div class="notice"><strong>Operations requested clarification:</strong><br><?=nl2br(h($load['clarification_request']??''))?><div class="actions"><a class="button" href="<?=h(Url::to('loads/clarify.php?id='.$id))?>">Respond to clarification</a></div></div><?php elseif($load['current_status']==='approved'):?><div class="success"><strong>Approved.</strong> This load is ready for the later transport workflow. Matching and assignment are not part of Phase 5B.</div><?php elseif($load['current_status']==='rejected'):?><div class="error"><strong>Rejected.</strong> This load is closed for Operations review.<?php if($load['decision_reason']):?><br><?=nl2br(h($load['decision_reason']))?><?php endif;?></div><?php else:?><div class="notice">This load version is read-only while it is in the Operations workflow.</div><?php endif;?><?php require BASE_PATH.'/app/Views/layout/footer.php';
